#include <stdio.h>
#include <string.h>

static int append_text(char *destination, size_t capacity, const char *source)
{
    size_t used = strlen(destination);
    size_t extra = strlen(source);

    if (used >= capacity || extra >= capacity - used) {
        return 0;
    }
    memmove(destination + used, source, extra + 1U);
    return 1;
}

int main(void)
{
    char message[32] = "C";
    const char suffix[] = " language";
    const char *word = "C language";

    if (!append_text(message, sizeof message, suffix)) {
        fputs("Not enough destination space.\n", stderr);
        return 1;
    }

    printf("Message: %s\n", message);
    printf("Length: %zu\n", strlen(message));
    printf("Comparison: %d\n", strcmp(message, word));

    if (!append_text(message, sizeof message, message + 2)) {
        puts("Second append did not fit.");
    } else {
        printf("After self-buffer append: %s\n", message);
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void)
{
    unsigned char source[] = {1U, 2U, 3U, 4U, 5U};
    unsigned char buffer[sizeof source];
    size_t i;

    memcpy(buffer, source, sizeof source);
    printf("Copied bytes equal: %s\n",
           memcmp(buffer, source, sizeof source) == 0 ? "yes" : "no");

    memmove(buffer + 1U, buffer, sizeof buffer - 1U);
    printf("After overlapping shift:");
    for (i = 0U; i < sizeof buffer; ++i) {
        printf(" %u", (unsigned int)buffer[i]);
    }
    putchar('\n');

    memset(buffer, 0, sizeof buffer);
    printf("After memset, first byte: %u\n", (unsigned int)buffer[0]);
    return 0;
}
